// Gather all data from parallel branches
const stats = $('Get Hub Stats').first()?.json || {};
const recentJobs = $('Get Recent Jobs').first()?.json?.jobs || [];
const hotPrograms = $('Get Hot Programs').first()?.json?.programs || [];
const aiIntel = $('Generate Weekly Intel').first()?.json || {};

// Calculate week-over-week metrics
const totalJobs = stats.total_jobs || 0;
const newJobs = recentJobs.length;
const totalContacts = stats.total_contacts || 0;
const totalPrograms = stats.total_programs || 0;

// Identify high-priority items
const highPriorityJobs = recentJobs.filter(job => {
    const clearance = (job.detected_clearance || '').toLowerCase();
    return clearance.includes('ts/sci') || clearance.includes('top secret');
});

// Top locations this week
const locationCounts = {};
recentJobs.forEach(job => {
    const loc = job.location || 'Unknown';
    locationCounts[loc] = (locationCounts[loc] || 0) + 1;
});
const topLocations = Object.entries(locationCounts)
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([loc, count]) => ({ location: loc, count }));

// Build report
const report = {
    report_type: "Weekly BD Intelligence",
    report_date: new Date().toISOString().split('T')[0],
    generated_at: new Date().toISOString(),

    executive_summary: aiIntel.summary ||
        `This week: ${newJobs} new jobs identified, ${highPriorityJobs.length} high-priority opportunities.`,

    metrics: {
        total_jobs_in_system: totalJobs,
        new_jobs_this_week: newJobs,
        high_priority_jobs: highPriorityJobs.length,
        total_contacts: totalContacts,
        total_programs: totalPrograms
    },

    hot_programs: hotPrograms.slice(0, 10).map(p => ({
        name: p.name,
        score: p.priority_score || p.score,
        reason: p.reason || 'High activity detected'
    })),

    top_locations: topLocations,

    high_priority_jobs: highPriorityJobs.slice(0, 10).map(j => ({
        title: j.title,
        company: j.company,
        location: j.location,
        clearance: j.detected_clearance,
        url: j.url
    })),

    ai_insights: aiIntel.insights || [],

    recommendations: aiIntel.recommendations || [
        "Review high-priority job listings",
        "Update contact database with new leads",
        "Schedule outreach for hot programs"
    ],

    next_week_focus: aiIntel.next_week_focus || []
};

return [{ json: report }];

const report = $input.first().json;

// Build Slack blocks for rich formatting
const message = `📊 *Weekly BD Intelligence Report*
_Week of ${report.report_date}_

*Executive Summary:*
${report.executive_summary}

*📈 This Week's Numbers:*
• New Jobs: ${report.metrics.new_jobs_this_week}
• High Priority: ${report.metrics.high_priority_jobs}
• Total Contacts: ${report.metrics.total_contacts}
• Total Programs: ${report.metrics.total_programs}

*🔥 Hot Programs:*
${report.hot_programs.slice(0, 5).map((p, i) =>
    `${i + 1}. ${p.name} (Score: ${p.score})`
).join('\n')}

*📍 Top Locations:*
${report.top_locations.map(l => `• ${l.location}: ${l.count} jobs`).join('\n')}

*✅ Recommended Actions:*
${report.recommendations.map(r => `• ${r}`).join('\n')}

_Full report available in the Hub dashboard_`;

return [{
    json: {
        message,
        report
    }
}];
